SELECT p.id AS id, p.order_id AS orderId, o.order_no AS orderNo, p.business_entity_id AS businessEntityId, be.name AS businessEntityName, c.name AS customerName, r.name AS resourceName, p.direction AS direction, p.type AS type, p.amount AS amount, p.occur_date AS occurDate, p.invoice_no AS invoiceNo, p.operator_id AS operatorId, p.remark AS remark, p.create_time AS createTime FROM ad_payment_record p LEFT JOIN ad_order o ON o.id = p.order_id AND o.deleted = 0 LEFT JOIN ad_business_entity be ON be.id = p.business_entity_id AND be.deleted = 0 LEFT JOIN ad_customer c ON c.id = o.customer_id AND c.deleted = 0 LEFT JOIN ad_resource r ON r.id = p.resource_id AND r.deleted = 0 WHERE p.organization_id = #{request.organizationId} AND p.deleted = 0
AND p.order_id = #{request.orderId}
AND p.business_entity_id = #{request.businessEntityId}
AND p.direction = #{request.direction}
AND p.type = #{request.type}
AND (o.order_no LIKE CONCAT('%', #{request.keyword}, '%') OR c.name LIKE CONCAT('%', #{request.keyword}, '%') OR p.invoice_no LIKE CONCAT('%', #{request.keyword}, '%'))
AND p.occur_date >= #{request.occurDateFrom}
AND p.occur_date <= #{request.occurDateTo}
AND p.business_entity_id IN
#{eid}
